// spec: .qa/e2e/specs/tender-drafts.md
// seed: tests/seed.company.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/company.json') });

const DRAFT = 'טיוטה – הפרסום לא הושלם';

test.describe('Tender drafts — «המכרזים שלי» (company)', () => {
  test('Unfinished tenders are listed with the mark «טיוטה – הפרסום לא הושלם» @desktop #bc890b', async ({ page }) => {
    // 1. Open /tenders → «המכרזים שלי»
    await page.goto('/tenders?mine=1');
    await expect(page.getByRole('heading', { level: 1, name: 'המכרזים שלי' })).toBeVisible();
    const cards = page.getByRole('listitem').filter({ has: page.getByRole('link', { name: /^לפרטי המכרז/ }) });
    await expect(cards.first()).toBeVisible();

    // Expected: at least one card has the badge «טיוטה – הפרסום לא הושלם»
    const drafts = cards.filter({ has: page.getByText(DRAFT, { exact: true }) });
    await expect(drafts.first()).toBeVisible();

    // Expected: a draft is never «ממתין לתשלום»; «ממתין לתשלום» appears only on paid («מכרז חם») tenders, not on a free one
    const texts = await cards.allInnerTexts();
    const bad = texts.filter((t) => (t.includes(DRAFT) && t.includes('ממתין לתשלום')) || (t.includes('ממתין לתשלום') && !t.includes('מכרז חם')));
    expect(bad.map((t) => t.replace(/\s+/g, ' ').slice(0, 80)), 'free/draft tender cards with «ממתין לתשלום»').toEqual([]);
  });
});
